// ─── File: src/main/java/com/bank/settlement/demo/AckModeDemo.java ───
// Runnable demo: processing-then-acknowledge, crash + replay, idempotent store.
package com.bank.settlement.demo;

import java.math.BigDecimal;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class AckModeDemo {

    private static final Logger log = Logger.getLogger("AckMode");
    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        SettlementStore store = new SettlementStore();
        SettlementConsumer consumer = new SettlementConsumer(store);

        List<TxnEvent> partition = List.of(
            new TxnEvent("TXN-1", "SAV2001", new BigDecimal("20000")),
            new TxnEvent("TXN-2", "SAV2001", new BigDecimal("30000")),
            new TxnEvent("TXN-3", "CUR3001", new BigDecimal("50000"))
        );

        ContainerSimulator container = new ContainerSimulator(consumer, partition);

        log.info("=== Run 1: crash AFTER settling TXN-2 but BEFORE acknowledging ===");
        container.run(/*crashAfterIndex*/ 1);   // committed offset stays at TXN-1

        log.info("=== Run 2: restart from last committed offset (TXN-2) ===");
        container.resume();  // TXN-2 redelivered, store dedups it, then TXN-3

        log.info(() -> "final settlements stored = " + store.size()
                + " (TXN-2 processed twice but stored once)");
    }
}

// ─── Would be in TxnEvent.java ───
class TxnEvent {
    final String txnId;
    final String accountId;
    final BigDecimal amount;
    TxnEvent(String txnId, String accountId, BigDecimal amount) {
        this.txnId = txnId;
        this.accountId = accountId;
        this.amount = amount;
    }
}

// ─── Would be in Acknowledgment.java (Spring provides this interface) ───
interface Acknowledgment {
    void acknowledge();
}

// ─── Would be in SettlementStore.java ───
// Idempotent store: re-processing the same txnId is a harmless no-op.
class SettlementStore {
    private static final Logger log = Logger.getLogger("AckMode");
    private final ConcurrentMap<String, BigDecimal> posted = new ConcurrentHashMap<>();

    boolean settle(TxnEvent e) {
        BigDecimal prev = posted.putIfAbsent(e.txnId, e.amount);
        if (prev != null) {
            log.warning(() -> "duplicate settle ignored txn=" + e.txnId + " (idempotent)");
            return false;
        }
        log.info(() -> "posted settlement txn=" + e.txnId + " account=" + e.accountId
                + " amount=Rs." + e.amount);
        return true;
    }
    int size() { return posted.size(); }
}

// ─── Would be in SettlementConsumer.java ───
// Processes first, acknowledges second = at-least-once.
class SettlementConsumer {
    private static final Logger log = Logger.getLogger("AckMode");
    private final SettlementStore store;
    SettlementConsumer(SettlementStore store) { this.store = store; }

    void onTxn(TxnEvent e, Acknowledgment ack) {
        store.settle(e);        // side effect first
        ack.acknowledge();      // only now advance the offset bookmark
        log.fine(() -> "acknowledged offset for txn=" + e.txnId);
    }
}

// ─── Would be in ContainerSimulator.java ───
// Models the listener container + the committed-offset bookmark.
class ContainerSimulator {
    private static final Logger log = Logger.getLogger("AckMode");
    private final SettlementConsumer consumer;
    private final List<TxnEvent> partition;
    private int committedOffset = 0;   // next index to read on restart

    ContainerSimulator(SettlementConsumer consumer, List<TxnEvent> partition) {
        this.consumer = consumer;
        this.partition = partition;
    }

    void run(int crashAfterIndex) {
        for (int i = committedOffset; i < partition.size(); i++) {
            TxnEvent e = partition.get(i);
            final int idx = i;
            // MANUAL_IMMEDIATE: acknowledge advances the committed bookmark.
            Acknowledgment ack = () -> committedOffset = idx + 1;
            consumer.onTxn(e, ack);
            if (i == crashAfterIndex) {
                // Simulate crash: work for TXN-2 done, but did the ack land?
                // onTxn already called ack, so model the crash BEFORE the commit flush.
                committedOffset = idx; // roll bookmark back: commit never flushed
                log.severe(() -> "CRASH after processing txn=" + e.txnId
                        + " but before commit flushed; committedOffset=" + committedOffset);
                return;
            }
        }
    }

    void resume() {
        log.info(() -> "restarting from committedOffset=" + committedOffset);
        for (int i = committedOffset; i < partition.size(); i++) {
            TxnEvent e = partition.get(i);
            final int idx = i;
            Acknowledgment ack = () -> committedOffset = idx + 1;
            consumer.onTxn(e, ack);
        }
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
